// Enlace de 10 Mbit/s. Cada usuario, cuando está activo, usa 1 Mbit/s.
// Cada usuario está activo el 10 % del tiempo, independiente de los demás.
function comb(n, k) { let r = 1; for (let i = 1; i <= k; i++) r = r * (n - k + i) / i; return r; }
function pMasDe(n, p, max) {            // P(más de `max` activos a la vez)
  let s = 0;
  for (let k = max + 1; k <= n; k++) s += comb(n, k) * p ** k * (1 - p) ** (n - k);
  return s;
}
console.log("circuitos reservados: caben 10 usuarios, siempre");
for (const n of [10, 20, 35, 50]) {
  const prob = pMasDe(n, 0.1, 10);
  console.log(`paquetes con ${String(n).padStart(2)} usuarios: P(mas de 10 activos a la vez) = ${(prob * 100).toFixed(4)} %`);
}

// Un mensaje se parte en paquetes numerados, viaja desordenado y se rearma.
const mensaje = "Camion 14 sale del deposito de Barracas a las 06:30 con 220 cajas para Cordoba. Confirmar recepcion.";
const TAM = 16; // caracteres de datos por paquete (de juguete; acá 1 caracter = 1 byte)

// Mezclador con semilla fija para que la salida sea siempre la misma
let s = 7;
const azar = () => (s = (s * 1103515245 + 12345) % 2147483648) / 2147483648;

// 1) partir: cada paquete lleva su número, el total y un pedazo del mensaje
const largo = new TextEncoder().encode(mensaje).length;
const total = Math.ceil(mensaje.length / TAM);
const paquetes = [];
for (let i = 0; i < total; i++) {
  paquetes.push({ n: i + 1, de: total, datos: mensaje.slice(i * TAM, (i + 1) * TAM) });
}
console.log(`mensaje: ${largo} bytes -> ${total} paquetes de hasta ${TAM} bytes`);

// 2) la red los entrega en cualquier orden
const llegada = [...paquetes];
for (let i = llegada.length - 1; i > 0; i--) {
  const j = Math.floor(azar() * (i + 1));
  [llegada[i], llegada[j]] = [llegada[j], llegada[i]];
}
console.log("orden de llegada:", llegada.map(p => p.n).join(" "));

// 3) el destino rearma: ordena por número y revisa que no falte ninguno
function rearmar(recibidos) {
  const porNumero = new Map(recibidos.map(p => [p.n, p]));
  const faltan = [];
  for (let n = 1; n <= recibidos[0].de; n++) if (!porNumero.has(n)) faltan.push(n);
  if (faltan.length) return { ok: false, faltan };
  let texto = "";
  for (let n = 1; n <= recibidos[0].de; n++) texto += porNumero.get(n).datos;
  return { ok: true, texto };
}
const r1 = rearmar(llegada);
console.log("rearmado:", r1.ok ? `"${r1.texto}"` : "faltan " + r1.faltan);
console.log("identico al original:", r1.texto === mensaje);

// 4) si se pierde un paquete, el destino sabe cuál pedir de nuevo
const conPerdida = llegada.filter(p => p.n !== 4);
const r2 = rearmar(conPerdida);
console.log("sin el paquete 4:", r2.ok ? "completo" : "faltan " + r2.faltan.join(", ") + " -> se pide solo ese");

// Tiempo para mandar un archivo por k enlaces en cadena (modelo ideal: sin
// demora de propagación, sin cabeceras, sin colas, cada nodo guarda y reenvía).
const bitsMensaje = 8_000_000;   // 1 MB = 8 millones de bits
const velocidad = 1_000_000;     // cada enlace: 1 Mbit/s
const enlaces = 3;               // origen -> nodo -> nodo -> destino

// A) el mensaje entero: cada nodo espera a tenerlo completo y recién lo reenvía
const entero = enlaces * (bitsMensaje / velocidad);
console.log(`mensaje entero, ${enlaces} enlaces: ${entero} s`);

// B) en paquetes de P bits: el primero ya avanza mientras el segundo sale
for (const P of [8_000_000, 800_000, 80_000, 8_000]) {
  const n = bitsMensaje / P;
  const tPaquete = P / velocidad;
  const t = (n + enlaces - 1) * tPaquete;
  console.log(`paquetes de ${String(P / 8).padStart(7)} bytes (${String(n).padStart(4)} paquetes): ${t.toFixed(3)} s`);
}
